head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// 반환값을 따옴표로 감싸고 typeof 도 함께 출력해 false 와 빈 문자열을 구분한다
scwin.printReadOnly = function (strLabel, objValue) {
    scwin.setReturnValue(strLabel + " : '" + objValue + "' (typeof " + (typeof objValue) + ")");
};

scwin.btn_run_onclick = function (e) {
    var objGrid = $p.getComponentById("target1");

    objGrid.setColumnReadOnly(0, true);
    scwin.printReadOnly("setColumnReadOnly(0, true) 후 getColumnReadOnly(0)", objGrid.getColumnReadOnly(0));

    objGrid.setColumnReadOnly(2, false);
    scwin.printReadOnly("setColumnReadOnly(2, false) 후 getColumnReadOnly(2)", objGrid.getColumnReadOnly(2));

    objGrid.setColumnReadOnly("col4", false);
    scwin.printReadOnly("setColumnReadOnly(\"col4\", false) 후 getColumnReadOnly(\"col4\")", objGrid.getColumnReadOnly("col4"));

    scwin.printReadOnly("readOnly 미설정 Column 의 getColumnReadOnly(1)", objGrid.getColumnReadOnly(1));
};
